  ui_story_31550401_83_dialog_content = "Nada mal! Isso é um latido bom e claro!",
  ui_story_31550401_84_dialog_content = "Agora que o pequeno barco afundou, vou terminar isso sozinho, com vocês dois como meus testemunhas!",
  ui_story_31550401_85_dialog_content = "Awuu!",
  ui_story_31550401_86_dialog_content = "Para enfrentar este mar terrível mais uma vez...",
  ui_story_31550401_87_dialog_content = "A água do mar fria e penetrante...",
