  ui_story_31550401_97_dialog_content = "Seria inútil explodir o mar... já que a água apenas convergiria para o mar novamente.",
  ui_story_31550401_98_dialog_content = "... Vou descansar um pouco primeiro, então, por favor, fiquem de guarda por mim, Sargentos.",
