  ui_story_31550401_100_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_102_dialog_content = "\"Eu realmente passei por algumas mudanças.\"",
  ui_story_31550401_103_dialog_content = "\"Mas eu sei que algumas coisas não podem ser mudadas...\"",
  ui_story_31550401_104_dialog_content = "Barton...",
