  ui_story_31550401_118_dialog_content = "Fale mais alto, eu não consigo te ouvir!!",
  ui_story_31550401_119_dialog_content = "Esplendor Illumina!!!",
  ui_story_31550401_120_dialog_content = "Excelente!!",
  ui_story_31550401_121_dialog_content = "Você já não sabe disso?",
  ui_story_31550401_122_dialog_content = "Você é um lutador, um soldado!",
  ui_story_31550401_123_dialog_content = "Você está cercado por inúmeros camaradas de armas que compartilham os mesmos interesses e crenças!",
  ui_story_31550401_124_dialog_content = "No entanto, não só você teme agora o poder formidável, mas também tem medo de perder o controle sobre ele e colocá-los em perigo?",
  ui_story_31550401_125_dialog_content = "Sim...",
  ui_story_31550401_126_dialog_content = "Isso é absurdo! Atenção!",
  ui_story_31550401_127_dialog_content = "Sim, senhor!",
  ui_story_31550401_128_dialog_content = "Você acha que é o único que pode se tornar um rei, Pequeno Barton?",
  ui_story_31550401_129_dialog_content = "Venha, Soldado, me diga como alguém se torna um rei?",
  ui_story_31550401_130_dialog_content = "Com determinação inabalável, você tem que esgotar todo o seu sangue e suor para acumular poder suficiente!",
