  ui_story_31550401_133_dialog_content = "Sim, senhor!",
  ui_story_31550401_134_dialog_content = "Coloque isso na sua cabeça...",
  ui_story_31550401_135_dialog_content = "Nunca decepcione seus companheiros, muito menos os subestime!",
  ui_story_31550401_136_dialog_content = "Sim, senhor!!",
  ui_story_31550401_137_dialog_content = "Tudo bem, então. Vá em frente e abrace seu poder que abrirá um novo caminho.",
  ui_story_31550401_138_dialog_content = "Nunca deixe nosso sangue ser derramado em vão!",
  ui_story_31550401_139_dialog_content = "Isso é uma ordem!",
  ui_story_31550401_140_dialog_content = "Sim, oficial Pango!!",
  ui_story_31550401_141_dialog_content = "Nossa!!",
  ui_story_31550401_142_dialog_content = "Awuuu!!",
  ui_story_31550401_143_dialog_content = "Ele finalmente se levantou. Eu não te disse que ele vai ficar bem?",
  ui_story_31550401_144_dialog_content = "Se o impressionante Comandante da Legião Barton fosse se afogar em uma selva como esta,",
  ui_story_31550401_145_dialog_content = "Illumina certamente cairá em desgraça, como Lumopolis.",
  ui_story_31550401_146_dialog_content = "Você está bem, Barton?",
  ui_story_31550401_147_dialog_content = "Sim, estou bem... Por que todos estão aqui?",
  ui_story_31550401_148_dialog_content = "Bem... Você não está aqui para aprender a nadar?",
  ui_story_31550401_149_dialog_content = "Todos estão bastante preocupados com você depois de desaparecer por tanto tempo sem dizer nada.",
  ui_story_31550401_150_dialog_content = "Aham, se preocupe com o meu a... Estou bem.",
  ui_story_31550401_151_dialog_content = "Mesmo que ele não consiga aprender a nadar, tenho certeza de que ele pode voltar cavando um túnel ou algo assim. Quer dizer, ele é o Barton, afinal de contas.",
  ui_story_31550401_152_dialog_content = "Hahaha, isso aí!",
  ui_story_31550401_153_dialog_content = "Já que todos estamos aqui, ninguém tem permissão para sair hoje. Vamos, vamos ter uma sessão de treinamento de natação juntos!",
  ui_story_31550401_154_dialog_content = "Pelo bem de estar preparado para quaisquer possíveis inimigos do mar...",
  ui_story_31550401_155_dialog_content = "Nós, Comandantes da Legião, devemos tomar a iniciativa de aprender a nadar corretamente!",
  ui_story_31550401_156_dialog_content = "Isso é interessante. Vamos lá, vamos ver quem é o melhor então.",
  ui_story_31550401_157_dialog_content = "Eh? Mas eu não trouxe um maiô...",
  ui_story_31550401_158_dialog_content = "Vamos lá. Faz séculos desde a última vez que tentei esportes aquáticos.",
  ui_story_31550401_159_dialog_content = "Eles simplesmente... fugiram para nadar assim...",
  ui_story_31550401_160_dialog_content = "De qualquer forma, tudo o que importa é que Barton está bem e parece muito mais energético agora.",
  ui_story_31550401_161_dialog_content = "No entanto, eu me pergunto quem é o \"Oficial Pango\" pelo qual ele continuava gritando em seu sono...",
  ui_story_31550401_162_dialog_content = "O nome soa bastante familiar, embora...",
  ui_story_31550601_1_dialog_content = "Ha, eu sabia que você viria, PlayerName!",
  ui_story_31550601_2_dialog_content = "Apenas porque sua mensagem soou tão urgente, Barton...",
  ui_story_31550601_3_dialog_content = "Isso é porque é urgente! Meu antigo oficial comandante finalmente acordou novamente!",
  ui_story_31550601_4_dialog_content = "Essa é uma das melhores notícias que já recebi na minha vida, e você é a primeira pessoa com quem eu queria compartilhar.",
  ui_story_31550601_5_dialog_content = "E, uh... Já que você está aqui, você se importaria em usar seus poderes para verificar o estado mental do Oficial Pango? Muito obrigado!",
  ui_story_31550601_6_dialog_content = "Então é por isso que você me chamou!",
  ui_story_31550601_7_dialog_content = "Hã? Agora que penso nisso, você não está usando essa roupa porque—",
  ui_story_31550601_8_dialog_content = "Isso mesmo. Estou preocupado que o comandante possa não me reconhecer, então eu desenterrei este antigo número.",
  ui_story_31550601_9_dialog_content = "Ele entrou em coma enquanto defendia a Cidade Gannon dos Eclipsitas. Essa batalha ocorreu há mais de dez anos.",
  ui_story_31550601_10_dialog_content = "Nesse tempo, passei de um recruta punk irritante para o excelente comandante que você vê hoje! É por isso que me preocupo que ele não me reconheça de imediato.",
  ui_story_31550601_11_dialog_content = "Duvido. Você ainda é Barton, afinal.",
  ui_story_31550601_12_dialog_content = "Tentei tanto ter conversas com ele durante todos esses anos, na esperança de que isso o acordasse algum dia...",
  ui_story_31550601_13_dialog_content = "Quando recebi a ligação de repente, fiquei sem palavras.",
  ui_story_31550601_14_dialog_content = "De qualquer forma, sou grato por você ter vindo. Venha, vamos entrar.",
  ui_story_31550601_15_dialog_content = "... Pare com toda essa cutucada e provocação, droga! Eu estou perfeitamente ciente do meu próprio corpo, muito obrigado!",
  ui_story_31550601_16_dialog_content = "Agora me deixem ir, seus idiotas! A luta ainda não acabou!",
  ui_story_31550601_17_dialog_content = "Barton?",
  ui_story_31550601_18_dialog_content = "Comandante Barton!",
  ui_story_31550601_19_dialog_content = "Oficial Pango... Você está realmente acordado...",
  ui_story_31550601_20_dialog_content = "... Por que diabos você está usando uma coisa tão estúpida? Deixa pra lá, você chegou na hora certa - diga a eles para me deixarem ir logo.",
  ui_story_31550601_21_dialog_content = "Eles estão me mantendo presa aqui, dizendo que é para o meu próprio bem ou algum absurdo assim.",
  ui_story_31550601_22_dialog_content = "Eles também estão me dizendo que a Crise Darkover terminou há mais de dez anos! Você pode acreditar nisso?",
  ui_story_31550601_23_dialog_content = "As linhas de frente estão em sério perigo. A Cidade Gannon foi completamente cercada...",
  ui_story_31550601_24_dialog_content = "Espere... Barton... Quando você começou a ter cabelos cinza?",
  ui_story_31550601_25_dialog_content = "Oficial Pango... A batalha terminou há muito tempo.",
  ui_story_31550601_26_dialog_content = "... Você também está vomitando as mesmas bobagens? Que diabos está acontecendo aqui?",
  ui_story_31550601_27_dialog_content = "E quem é aquele novo recruta de aparência fraca? A Illumina baixou seus padrões de alistamento novamente?",
  ui_story_31550601_28_dialog_content = "Olá, senhor. Na verdade, eu sou—",
  ui_story_31550601_29_dialog_content = "Preciso voltar para a batalha, agora faça acontecer! Essa é uma ordem, Barton!",
  ui_story_31550601_30_dialog_content = "Estou cansado de todas essas bandagens e agulhas! Me mande de volta para a linha de frente, para que eu possa tomar um pouco de ar fresco!",
  ui_story_31550601_31_dialog_content = "Tenho certeza de que tudo fará sentido quando eu voltar lá...",
  ui_story_31550601_32_dialog_content = "Sim, senhor!",
  ui_story_31550601_33_dialog_content = "O que você acha da recuperação do Oficial Pango, PlayerName? O estado mental dele... está normal?",
  ui_story_31550601_34_option_content = "Sentir Pango",
  ui_story_31550601_35_dialog_content = "Espere... O que é essa sensação?",
  ui_story_31550601_36_dialog_content = "Ele está perfeitamente bem... Ele só está tendo dificuldade em acreditar no que os outros dizem, é só isso.",
  ui_story_31550601_37_dialog_content = "Obrigado... Vamos, senhor. Não está fácil para você se movimentar agora, mas é para isso que essas cadeiras de rodas servem.",
  ui_story_31550601_38_dialog_content = "O que é isso, Barton? Por que você me trouxe para um museu?",
  ui_story_31550601_39_dialog_content = "Tenho certeza de que eles te contaram tudo quando você acordou pela primeira vez, oficial Pango.",
  ui_story_31550601_40_dialog_content = "Você estava em coma por mais de uma década. A Crise Darkover também terminou há muito tempo.",
  ui_story_31550601_41_dialog_content = "Como você pode ver, seu inútil antigo subordinado é agora o comandante da 2ª Legião.",
  ui_story_31550601_42_dialog_content = "Isto é... Minha placa de identificação?",
  ui_story_31550601_43_dialog_content = "Isso mesmo, senhor. Você deixou isso comigo todos esses anos atrás.",
  ui_story_31550601_44_dialog_content = "Você ainda se lembra daquele dia? No final da crise, você nos disse para recuar, mas ficou para lutar.",
  ui_story_31550601_45_dialog_content = "Estamos todos seguros agora, senhor. Tudo o que aconteceu está no passado agora.",
  ui_story_31550601_46_dialog_content = "Impossível...",
  ui_story_31550601_47_dialog_content = "E agora, vamos voltar nossa atenção para os esforços valentes da Divisão de Máquinas da 2ª Legião durante a Crise de Darkover.",
  ui_story_31550601_48_dialog_content = "!",
  ui_story_31550601_49_dialog_content = "Como todos vocês já leram antes, até mesmo a cidade de Gannon caiu para a incursão dos Eclipsites no auge da Crise Darkover.",
  ui_story_31550601_50_dialog_content = "Para facilitar a evacuação da cidade, cada membro da 2ª Legião ficou para trás para continuar lutando contra o inimigo.",
  ui_story_31550601_51_dialog_content = "O tanque que você vê à sua frente é um Modelo L3 de Illumina, e este em particular foi operado pela 2ª Legião durante aquela batalha.",
  ui_story_31550601_52_dialog_content = "Uau—",
  ui_story_31550601_53_dialog_content = "Esse é o nosso tanque, Barton... O que aconteceu com ele? Por que está... todo quebrado?",
  ui_story_31550601_54_dialog_content = "Porque deu tudo o que tinha para salvar a Cidade Gannon, senhor, assim como você.",
  ui_story_31550601_55_dialog_content = "Apesar de seu dano, ainda não se aposentou. Ele vive neste museu para ensinar e inspirar as futuras gerações.",
  ui_story_31550601_56_dialog_content = "Este tanque é um veterano imortal da 2ª Legião.",
  ui_story_31550601_57_dialog_content = "Comandante Barton? Não estávamos esperando você hoje, senhor. Me desculpe, mas seu convidado...",
  ui_story_31550601_58_dialog_content = "É... É realmente você? O lendário guardião da Torre Central?",
  ui_story_31550601_59_dialog_content = "É realmente você! Você finalmente acordou, Comandante Pango!",
  ui_story_31550601_60_dialog_content = "O quê? Ele realmente acordou do coma?",
  ui_story_31550601_61_dialog_content = "Pango? Você quer dizer o lendário comandante que liderou um grupo de veteranos para defender a Torre Central? Onde?",
  ui_story_31550601_62_dialog_content = "Oficial Pango! Tem certeza de que deveria estar se movendo agora? Queremos treinar sob sua orientação, senhor!",
  ui_story_31550601_63_dialog_content = "Ei! Mostrem algum respeito ao oficial, seus arruaceiros! Se querem fazer perguntas, façam-nas uma de cada vez!",
  ui_story_31550601_64_dialog_content = "Sim, senhor!",
  ui_story_31550601_65_dialog_content = "Oficial Pango! Você não me conhece, mas eu venho da nova Subcidade 13.",
  ui_story_31550601_66_dialog_content = "Se não fosse por você e o Comandante Wrath, a Subcidade 13 teria sido completamente aniquilada.",
  ui_story_31550601_67_dialog_content = "Então obrigado... Obrigado por nos salvar e por nos dar a chance de reconstruir nossa casa.",
  ui_story_31550601_68_dialog_content = "A \"nova\" Subcidade 13?",
  ui_story_31550601_69_dialog_content = "Minha vez! Saudações, Oficial Pango! Eu nasci e fui criado em um dos distritos mais antigos da Cidade Gannon.",
  ui_story_31550601_70_dialog_content = "Graças à sua coragem, toda a minha família foi mantida a salvo dos Eclipsitas.",
  ui_story_31550601_71_dialog_content = "Eu era apenas uma criança quando retomamos a cidade, mas me alistei assim que atingi a maioridade! Meu sonho é me tornar um herói como você, senhor!",
  ui_story_31550601_72_dialog_content = "\"Retomou a cidade\"...",
  ui_story_31550601_73_dialog_content = "Tudo bem, isso é o suficiente por enquanto. Dê algum espaço ao oficial.",
  ui_story_31550601_74_dialog_content = "Hmm? Bem, se não é nosso querido camarada, o Celestita! Bem-vindo de volta a Illumina, meu amigo.",
  ui_story_31550601_75_dialog_content = "Prazer em estar de volta!",
  ui_story_31550601_76_dialog_content = "Você é um Celestita? Mas durante a Crise Darkover, Eraveil já tinha...",
  ui_story_31550601_77_dialog_content = "... Eu sei. A verdade é, eu sou—",
  ui_story_31550601_78_dialog_content = "PlayerName teve sorte o suficiente para sobreviver ao ataque em Eraveil! Algo me diz que há muitos outros Celestitas esperando por ele lá fora!",
  ui_story_31550601_79_dialog_content = "Muitas coisas melhoraram nos anos desde a Crise Darkover, senhor.",
  ui_story_31550601_80_dialog_content = "Então realmente ganhamos? Astra está realmente em paz novamente?",
  ui_story_31550601_81_dialog_content = "Sim, senhor. Nós vencemos... Embora a paz que garantimos não seja perfeita, conseguimos sobreviver à Crise Darkover.",
  ui_story_31550601_82_dialog_content = "A Subcidade 13 foi reconstruída, juntamente com a Cidade Gannon. Nossas futuras gerações não estão mais sendo criadas nas trincheiras da guerra.",
  ui_story_31550601_83_dialog_content = "... Eu me vi no espelho quando acordei esta manhã.",
  ui_story_31550601_84_dialog_content = "Todo esse cabelo branco na minha cabeça... Acho que não era por causa das minhas lesões afinal.",
  ui_story_31550601_85_dialog_content = "Ainda assim, parece que o tempo curou muitas coisas também.",
  ui_story_31550601_86_dialog_content = "Mesmo que... Eu tenha perdido tanto tempo eu mesmo...",
  ui_story_31550601_87_dialog_content = "Você amadureceu tanto no que parece um piscar de olhos, Barton.",
  ui_story_31550601_88_dialog_content = "O seu treinamento é o que me moldou em um pilar da Federação Illumina, senhor.",
  ui_story_31550601_89_dialog_content = "Sei exatamente quais são os meus deveres e lidero nossos soldados para a frente sem qualquer dúvida no meu coração. A 2ª Legião está em boas mãos, então, por favor, concentre-se em descansar e se recuperar, senhor.",
  ui_story_31550601_90_dialog_content = "... Heh. O Barton que eu conhecia não falaria assim de jeito nenhum.",
  ui_story_31550601_91_dialog_content = "Levaria-me para ver o monumento, você faria isso?",
  ui_story_31550601_92_dialog_content = "Sim, senhor.",
  ui_story_31550601_93_dialog_content = "Também quero ver como a 2ª Legião está se saindo agora.",
  ui_story_31550601_94_dialog_content = "Afinal, alguém tem que garantir que você não estragou tudo.",
  ui_story_31550601_95_dialog_content = "Se eu descobrir que você estava apenas falando bobagens agora, vou te submeter ao mesmo treinamento brutal que fiz antes!",
  ui_story_31550601_96_dialog_content = "Entendido, senhor!",
  ui_story_31550601_97_dialog_content = "Er, Oficial Pango...",
  ui_story_31550601_98_dialog_content = "O que foi?",
  ui_story_31550601_99_dialog_content = "Foi uma honra conhecê-lo, assim como o Comandante Barton e o Celestita.",
  ui_story_31550601_100_dialog_content = "Você se sacrificou tanto para nos ajudar, e para ajudar todo o Astra.",
  ui_story_31550601_101_dialog_content = "Seria aceitável se nós... tirássemos uma foto para comemorar este dia? Por favor?",
  ui_story_31550601_102_dialog_content = "Claro.",
  ui_story_31550601_103_dialog_content = "Ha! Venha pra cá, PlayerName! Você não tem uma chance assim o tempo todo, então aproveite!",
  ui_story_31550601_104_dialog_content = "Uma foto em grupo com dois lendários heróis de guerra? Não vou mentir, estou um pouco nervoso...",
  ui_story_31550601_105_dialog_content = "Você vai superar isso! Além disso, você é uma aliada importante na luta também!",
  ui_story_31550601_106_dialog_content = "Todos prontos? Bom! Agora olhem para a câmera e repitam depois de mim — Splendor Illumina!",
  ui_story_31550601_107_dialog_content = "Splendor Illumina!",
  ui_story_31550601_108_dialog_content = "Está pronto! Venha olhar!",
  ui_story_31550601_109_dialog_content = "Ainda pareço muito nervoso...",
  ui_story_31550601_110_dialog_content = "Heheh, e eu continuo fotogênico como sempre!",
  ui_story_31550601_111_dialog_content = "...",
  ui_story_31550601_112_dialog_content = "Lembro de tirar uma foto assim antes...",
  ui_story_31550601_113_dialog_content = "Ah! Isso mesmo... Nossa antiga foto do grupo...",
  ui_story_31550601_114_dialog_content = "Tudo bem, agora todos sorriam bastante desta vez — Splendor Illumina!",
  ui_story_31550601_115_dialog_content = "<size=45>Splendor Illumina!</size>",
  ui_story_31550601_116_dialog_content = "As crianças da 2ª Legião...",
  ui_story_31550601_117_dialog_content = "Você se tornou as estrelas que iluminam o caminho dos outros?"
}
return config
